 Here's an updated version of the `CreateObjectView` component with added ID attributes for easier selection and manipulation using JavaScript:

```jsx
import React, { useState, useEffect } from 'react';
import { observer } from 'mobx-react';
import { action } from 'mobx';

import CreateObjectModel from './CreateObjectModel';
import AssetListItem from '../assets/AssetListItem';

const CreateObjectView = observer(({ model }) => {
  const [selectedAssetId, setSelectedAssetId] = useState(null);

  useEffect(() => {
    // Clean up scene when component unmounts
    return () => model.cleanupScene();
  }, []);

  const handleSelectAsset = id => {
    setSelectedAssetId(id);
    model.setSelectedAsset(id);
  };

  const handleCreateObject = () => {
    if (selectedAssetId) {
      model.createObject(selectedAssetId).then(() => {
        // Clear selected asset after object creation
        setSelectedAssetId(null);
      });
    }
  };

  return (
    <div id="create-object-view">
      <h2>Create Object</h2>
      <div className="asset-list">
        {model.availableAssets.map(asset => (
          <AssetListItem
            key={asset.id}
            id={asset.id}
            name={asset.name}
            select={() => handleSelectAsset(asset.id)}
            selected={selectedAssetId === asset.id}
          />
        ))}
      </div>
      <button onClick={handleCreateObject} disabled={!selectedAssetId}>
        Create Object
      </button>
      <button id="cleanup-scene" onClick={model.cleanupScene}>
        Cleanup Scene
      </button>
      <CreateObjectModel model={model} />
    </div>
  );
});

export default CreateObjectView;
```

