```js
const axios = require('axios');

function sendMessageToSlackChannel(text, channel) {
  const webhookUrl = process.env.SLACK_WEBHOOK_URL;
  const payload = {
    text,
    channel,
    username: 'MyApp',
    icon_emoji: ':robot:'
  };

  return axios.post(webhookUrl, JSON.stringify(payload))
