    public static void main(String[] args) throws Exception {
        List<String> inputFiles = getInputFiles(); // gets list of input audio files
        String outputFile = "output.wav"; // name of output audio file

        SoxRewriter rewriter = new SoxRewriter()
            .input("in")
            .inputs(inputFiles)
            .outputFormat(SoxFormat.WAV)
            .output(outputFile);

        // add volume adjustment
        rewriter.addEffect(new VolumeEffect(-3));
        // add fade in/out effect
