    for (let I = 0; I < sortedKeys.length; i++) {
      const leftVal = a[sortedKeys[i]] ?? ""; // Get the value for the current key or default to an empty string
      const rightVal = b[sortedKeys[i]] ?? "";
      const valCompare = leftVal.localeCompare(rightVal); // Compare the values using localeCompare for case-insensitive comparison
