    // Calculate original purchase price less residual value
    const double ORIGINAL_PURCHASE_PRICE = PURCHASE_PRICE - RESIDUAL_VALUE;

    // Calculate percentage of refund
    const double PERCENTAGE_OF_REFUND = (AGREED_REFUND_AMOUNT / ORIGINAL_PURCHASE_PRICE) * 100;

    std::cout << "Percentage of refund: " << PERCENTAGE_OF_REFUND << "%" << std::endl;

    return 0;
}
