#include <iostream>
#include <string>
#include <sstream>
#include <limits>

// Function to generate Fibonacci sequence recursively
unsigned long long fibonacci(int n, int first, int second) {
    if (n <= 1) { // Base case: return first or second
        return n == 0 ? first : second;
    }
    else { // Recursive case: sum of previous two numbers
        return fibonacci(n - 1, first, second) + fibonacci(n - 2, first, second);
    }
}

int main() {
    int first, second, numElements;
    std::cout << "Enter the first two Fibonacci numbers: ";
    if (!(std::cin >> first >> second)) { // Error handling for non-numeric input
        std::cout << "Invalid input! Please enter integer values.\n";
        return 1;
    }
    if (first < 0 || second < 0) { // Error handling for negative numbers
        std::cout << "Invalid input! Please enter non-negative integer values.\n";
        return 1;
    }
    std::cout << "Enter the number of sequence elements to generate: ";
    if (! (std::cin >> numElements) || numElements < 1) { // Error handling for non-numeric or invalid input
        std::cout << "Invalid input! Please enter a positive integer value.\n";
        return 1;
    }
    std::cout << "Fibonacci sequence:\n";
    for (int I = 0; I < numElements; i++) {
        std::cout << fibonacci(i, first, second) << ", ";
    }
    std::cout << fibonacci(numElements, first, second); // Print last element without trailing comma
    std::cout << '\n';
