```php
function smart_sort_array($set, $order) {
    usort($set, function ($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];

        if ($ageA === $ageB) {
            return 0; // If ages are equal, don't change order
        }

        return $order ? $ageA > $ageB : $ageA < $ageB; // Sort based on order parameter
    });

    return $set;
}
```

