To extract and organize data from multiple sources with different formats into a coherent timeline, you can use a combination of R packages such as xml2, rjson, readr, lubridate, and ggplot2. Here's an example:

1. Define functions to parse each data format:

```R
# Function to parse XML files
xml_parse <- function(file) {
  library(xml2)
  xml_data <- xml_parse(file)
  events <- xml_nodes(xml_data, "event") %>%
    map(function(x) {
      event_date <- as.Date(xml_attr(x, "date"), format="%Y-%m-%d")
      event_name <- xml_text(x, trim=TRUE)
      list(date=event_date, name=event_name)
    })
  return(events)
}

# Function to parse CSV files
csv_parse <- function(file) {
  library(readr)
  csv_data <- read_csv(file)
  events <- csv_data %>%
    mutate(date = ymd(date)) %>%
    select(date, name) %>%
    as.list()
  return(events)
}

# Function to parse JSON files
json_parse <- function(file) {
  library(rjson)
  json_data <- fromJSON(file)
  events <- json_data %>%
    map(function(x) {
      event_date <- Sys.time() - as.POSIXct("1970-01-01", tz="GMT") + lubridate::ydm(x$date)
      event_name <- x$name
      list(date=event_date, name=event_name)
    })
  return(events)
}
