];

function getWeightedPosition(item) {
  const weightedRating = item.helpfulness * 87 + item.verbosity * 50;
  return Math.floor(Math.random() * (weightedRating * 2)) + 1; // Generate a random number between 1 and twice the weighted rating
}

let resultArray = [];
for (let I = 0; I < inputArray.length; i++) {
  const item = inputArray[i];
  let position = item.position - 1;
