```
// write isEven by using if 20 times
function isEven(n) {
 if (n == 0) {
 return true;
 } else if (n == 1) {
 return false;
 } else if (n == 2) {
 return true;
 } else if (n == 3) {
 return false;
 } else if (n == 4) {
 return true;
 } else if (n == 5) {
 return false;
 } else if (n == 6) {
 return true;
 } else if (n == 7) {
 return false;
 } else if (n == 8) {
 return true;
