```typescript
import { createInjectable } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { NestMiddleware } from './middleware.interface';
import { LoggerService } from './logger.service';

@createInjectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  constructor(private logger: LoggerService) {}

  use(context: NestMiddlewareContext, next: () => Promise<any>) {
    const env = process.env.NODE_ENV;

    if (env === 'production') {
      return next();
    }

    this.logger.log(`Development-only route called!`);

    context.res.statusCode = 401;
    context.res.setHeader('Content-Type', 'application/json');
    context.res.write(JSON.stringify({ message: 'Unauthorized' }));
    context.res.end();

    return new Promise(() => {});
  }
}

export function DevelopmentOnly() {
  return createNestMiddlewareProvider(DevelopmentOnlyMiddleware);
}

function createNestMiddlewareProvider(middleWareClass: typeof DevelopmentOnlyMiddleware): any {
  return {
    provide: 'dev_only_middleware',
    useFactory: () => middleWareClass,
    inject: [LoggerService],
  };
}

